(async function() {
  let state = await lf.ready;
  let activeTab = 'discover';

  const noticeContainer = document.getElementById('notice-container');
  const cardStackContainer = document.getElementById('card-stack-container');
  const actionsContainer = document.getElementById('actions-container');
  const favoritesGrid = document.getElementById('favorites-grid');
  const discoverView = document.getElementById('discover-view');
  const favoritesView = document.getElementById('favorites-view');
  const addForm = document.getElementById('add-photo-form');
  const passBtn = document.getElementById('pass-btn');
  const favBtn = document.getElementById('fav-btn');

  function renderNotice() {
    if (state.preview) {
      noticeContainer.innerHTML = `<div class="notice">Preview Mode: Mutations are read-only in this banner.</div>`;
    } else {
      noticeContainer.innerHTML = '';
    }
  }

  async function render() {
    renderNotice();

    // Switch views
    if (activeTab === 'discover') {
      discoverView.style.display = 'flex';
      favoritesView.style.display = 'none';
      await renderDiscover();
    } else {
      discoverView.style.display = 'none';
      favoritesView.style.display = 'grid';
      renderFavorites();
    }
  }

  async function renderDiscover() {
    // Find photos with no decision yet (decision is undefined or empty)
    const records = state.records || [];
    const undiscovered = records.filter(r => !r.values.decision);

    if (undiscovered.length === 0) {
      cardStackContainer.innerHTML = `
        <div class="empty-state">
          <h3>No more photos</h3>
          <p>You've reviewed everything! Add a new photo below to keep drifting.</p>
        </div>
      `;
      actionsContainer.style.display = 'none';
      return;
    }

    actionsContainer.style.display = 'flex';
    // Render top card
    const topRecord = undiscovered[0];
    let imgSrc = '';
    if (topRecord.values.assetId) {
      const imgRes = await lf.image(topRecord.values.assetId);
      imgSrc = imgRes.dataUrl;
    }

    cardStackContainer.innerHTML = `
      <div class="photo-card" id="current-card">
        <img src="${imgSrc}" alt="${topRecord.values.caption || 'Photo'}" />
        <div class="photo-info">
          <div class="photo-caption">${escapeHtml(topRecord.values.caption || '')}</div>
        </div>
      </div>
    `;

    setupSwipe(topRecord.id);
  }

  async function renderFavorites() {
    const records = state.records || [];
    const favorites = records.filter(r => r.values.decision === 'favorite');

    if (favorites.length === 0) {
      favoritesGrid.innerHTML = `
        <div class="empty-state" style="grid-column: 1 / -1;">
          <h3>No favorites yet</h3>
          <p>Swipe right or click the heart button on photos you love!</p>
        </div>
      `;
      return;
    }

    let html = '';
    for (const r of favorites) {
      let imgSrc = '';
      if (r.values.assetId) {
        const imgRes = await lf.image(r.values.assetId);
        imgSrc = imgRes.dataUrl;
      }
      html += `
        <div class="favorite-item">
          <img src="${imgSrc}" alt="${escapeHtml(r.values.caption || '')}" />
          <div class="caption">${escapeHtml(r.values.caption || '')}</div>
        </div>
      `;
    }
    favoritesGrid.innerHTML = html;
  }

  function setupSwipe(recordId) {
    const card = document.getElementById('current-card');
    if (!card) return;

    let startX = 0;
    let currentX = 0;
    let isDragging = false;

    card.addEventListener('pointerdown', (e) => {
      isDragging = true;
      startX = e.clientX;
      card.setPointerCapture(e.pointerId);
    });

    card.addEventListener('pointermove', (e) => {
      if (!isDragging) return;
      currentX = e.clientX - startX;
      const rot = currentX * 0.05;
      card.style.transform = `translateX(${currentX}px) rotate(${rot}deg)`;
    });

    card.addEventListener('pointerup', async (e) => {
      if (!isDragging) return;
      isDragging = false;
      card.releasePointerCapture(e.pointerId);

      if (currentX > 100) {
        await makeDecision(recordId, 'favorite');
      } else if (currentX < -100) {
        await makeDecision(recordId, 'pass');
      } else {
        card.style.transform = 'translateX(0) rotate(0deg)';
      }
    });
  }

  async function makeDecision(recordId, decision) {
    try {
      state = await lf.update(recordId, { decision });
      render();
    } catch (err) {
      noticeContainer.innerHTML = `<div class="notice">Failed to save decision: ${escapeHtml(err.message)}</div>`;
    }
  }

  passBtn.addEventListener('click', async () => {
    const records = state.records || [];
    const undiscovered = records.filter(r => !r.values.decision);
    if (undiscovered.length > 0) {
      await makeDecision(undiscovered[0].id, 'pass');
    }
  });

  favBtn.addEventListener('click', async () => {
    const records = state.records || [];
    const undiscovered = records.filter(r => !r.values.decision);
    if (undiscovered.length > 0) {
      await makeDecision(undiscovered[0].id, 'favorite');
    }
  });

  document.querySelectorAll('.tab-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
      e.target.classList.add('active');
      activeTab = e.target.getAttribute('data-tab');
      render();
    });
  });

  addForm.addEventListener('submit', async (e) => {
    e.preventDefault();
    const captionInput = document.getElementById('photo-caption-input');
    const fileInput = document.getElementById('photo-file-input');

    if (fileInput.files && fileInput.files[0]) {
      try {
        const imgPick = await lf.pickImage();
        if (imgPick && imgPick.assetId) {
          state = await lf.create({
            caption: captionInput.value,
            assetId: imgPick.assetId,
            decision: ''
          });
          captionInput.value = '';
          fileInput.value = '';
          render();
        }
      } catch (err) {
        noticeContainer.innerHTML = `<div class="notice">Failed to upload photo: ${escapeHtml(err.message)}</div>`;
      }
    }
  });

  function escapeHtml(str) {
    return str.replace(/[&<>'"]/g, 
      tag => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[tag] || tag)
    );
  }

  lf.subscribe(next => {
    state = next;
    render();
  });

  await render();
  lf.reportReady();
})();

